def isValid(word: str) -> bool:
    if len(word) < 3:
        return False

    vowels = set("aeiouAEIOU")
    has_vowel = False
    has_consonant = False

    for char in word:
        # Check if character is alphanumeric
        if not char.isalnum():
            return False

        # Check if it's a letter to determine if it's a vowel or consonant
        if char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                has_consonant = True

    return has_vowel and has_consonant
```

