def latestTime(s: str) -> str:
    # Convert string to list for mutability
    res = list(s)

    # Handle HH (Hours)
    # First digit of hour
    if res[0] == '?':
        # If second digit is '?' or <= 1, we can set first digit to '1' (for 10 or 11)
        # If second digit is > 1, we must set first digit to '0' (since max is 11)
        if res[1] == '?' or res[1] <= '1':
            res[0] = '1'
        else:
            res[0] = '0'

    # Second digit of hour
    if res[1] == '?':
        # If first digit is '0', max second digit is '9'
        # If first digit is '1', max second digit is '1'
        if res[0] == '0':
            res[1] = '9'
        else:
            res[1] = '1'

    # Handle MM (Minutes)
    # First digit of minute (0-5)
    if res[3] == '?':
        res[3] = '5'

    # Second digit of minute (0-9)
    if res[4] == '?':
        res[4] = '9'

    return "".join(res)
```

