import sys

# Increase recursion depth for deep DFS if necessary, 
# though we use an iterative BFS here for safety.
sys.setrecursionlimit(2000000)

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    # Precompute which cells are "frozen" (adjacent to a magnet)
    # frozen[i][j] is True if cell (i, j) is adjacent to at least one magnet
    frozen = [[False for _ in range(W)] for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                # Mark neighbors as frozen
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        frozen[nr][nc] = True

    visited = [[False for _ in range(W)] for _ in range(H)]
    max_freedom = 0

    # Iterate through all possible starting cells
    for r in range(H):
        for c in range(W):
            # Only start BFS from an empty cell that hasn't been visited
            if grid[r][c] == '.' and not visited[r][c]:
                # BFS to find the connected component of reachable cells
                component_size = 0
                queue = [(r, c)]
                visited[r][c] = True

                idx = 0
                while idx < len(queue):
                    curr_r, curr_c = queue[idx]
                    idx += 1
                    component_size += 1

                    # Takahashi can move if he is NOT frozen
                    if not frozen[curr_r][curr_c]:
                        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                if component_size > max_freedom:
                    max_freedom = component_size

    print(max_freedom)

if __name__ == "__main__":
    solve()

```

