import sys

def solve():
    # Read all input and split into lines
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    # Parse polyominoes from the 12 lines of input
    polyominoes_raw = []
    for i in range(0, 12, 4):
        grid = [list(line) for line in input_data[i:i+4]]
        polyominoes_raw.append(grid)

    def rotate(shape):
        """Rotate a 4x4 grid 90 degrees clockwise."""
        new_shape = [['.' for _ in range(4)] for _ in range(4)]
        for r in range(4):
            for c in range(4):
                new_shape[c][3-r] = shape[r][c]
        return new_shape

    def get_coords(shape):
        """Convert a 4x4 grid to a set of (r, c) coordinates of '#'."""
        coords = []
        for r in range(4):
            for c in range(4):
                if shape[r][c] == '#':
                    coords.append((r, c))
        return coords

    def normalize(coords):
        """Shift coordinates so the top-leftmost cell is (0, 0)."""
        if not coords: return coords
        min_r = min(r for r, c in coords)
        min_c = min(c for r, c in coords)
        return sorted([(r - min_r, c - min_c) for r, c in coords])

    # Pre-calculate all 4 rotations for each polyomino
    all_variants = []
    for p in polyominoes_raw:
        variants = []
        curr = p
        for _ in range(4):
            variants.append(normalize(get_coords(curr)))
            curr = rotate(curr)
        # Remove duplicate rotations for efficiency
        unique_variants = []
        for v in variants:
            if v not in unique_variants:
                unique_variants.append(v)
        all_variants.append(unique_variants)

    # total squares must be 16 for it to be possible
    total_squares = sum(len(v[0]) for v in all_variants)
    if total_squares != 16:
        print("No")
        return

    grid = [[False for _ in range(4)] for _ in range(4)]

    def can_place(coords, dr, dc):
        """Check if the polyomino can be placed at offset (dr, dc)."""
        for r, c in coords:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < 4 and 0 <= nc < 4) or grid[nr][nc]:
                return False
        return True

    def place(coords, dr, dc, val):
        """Place or remove the polyomino on the grid."""
        for r, c in coords:
            grid[r + dr][c + dc] = val

    def backtrack(p_idx):
        """Recursive function to try and fit polyominoes."""
        if p_idx == 3:
            return True

        # Try every rotation
        for variant in all_variants[p_idx]:
            # Try every possible translation
            for dr in range(-4, 4):
                for dc in range(-4, 4):
                    if can_place(variant, dr, dc):
                        place(variant, dr, dc, True)
                        if backtrack(p_idx + 1):
                            return True
                        place(variant, dr, dc, False)
        return False

    if backtrack(0):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

```

