import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    INF = float('inf')
    # Initialize distance matrix with infinity
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = min(dist[u][v], w)
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    # Since there are no negative cycles, this is safe.
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][k] != INF and dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_vertex] = min weight to visit vertices in mask
    # N is up to 20, so 2^20 * 20 is roughly 20 million, which fits in memory and time.
    num_states = 1 << N
    dp = [[INF] * N for _ in range(num_states)]

    # Base case: start at any vertex
    for i in range(N):
        dp[1 << i][i] = 0

    # Iterate through all subsets of vertices
    for mask in range(1, num_states):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try moving to vertex v that hasn't been visited yet
            # To minimize total distance, we use the shortest path from u to v
            for v in range(N):
                if not (mask & (1 << v)):
                    if dist[u][v] != INF:
                        new_mask = mask | (1 << v)
                        new_dist = dp[mask][u] + dist[u][v]
                        if new_dist < dp[new_mask][v]:
                            dp[new_mask][v] = new_dist

    # The answer is the minimum of dp[(1 << N) - 1][i] for all i
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[final_mask][i])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

```

Looking at this problem, I need to count numbers in [low, high] that have equal even/odd digit counts AND are divisible by k. With high up to 10⁹, I'll use **digit DP** with memoization.

**Key insights:**
- Track `position`, `diff` (even_count - odd_count offset by 10), `remainder mod k`, `tight` (upper bound constraint), and `started` (to handle leading zeros properly)
- A number is beautiful when `diff == 10` (actual diff = 0) and `remainder == 0`

**State space:** ~10 positions × 21 diff values × 20 remainders × 2 tight × 2 started ≈ 16,800 states — very efficient.

I verified against all three examples by tracing through the logic.

```python
def count_beautiful(low, high, k):
    def count_upto(n):
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        length = len(digits)

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, diff, rem, tight, started):
            if pos == length:
                if started and diff == 10 and rem == 0:
                    return 1
                return 0

            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                new_started = started or (d != 0)
                new_diff = diff
                if new_started:
                    if d % 2 == 0:
                        new_diff += 1
                    else:
                        new_diff -= 1
                new_rem = (rem * 10 + d) % k
                new_tight = tight and (d == limit)
                total += dp(pos + 1, new_diff, new_rem, new_tight, new_started)
            return total

        return dp(0, 10, 0, True, False)

    return count_upto(high) - count_upto(low - 1)
```

