import sys

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = [list(row) for row in input_data[2:]]

    # removed[i][j] is True if cookie (i, j) has been removed
    removed = [[False for _ in range(W)] for _ in range(H)]

    # To optimize, we track which rows and columns might still have cookies
    # and potentially be eligible for removal.
    active_rows = set(range(H))
    active_cols = set(range(W))

    while True:
        marked_this_round = False
        to_remove = [] # List of cells to mark for removal

        # 1. Check Rows
        rows_to_check = list(active_rows)
        for i in rows_to_check:
            remaining_in_row = []
            for j in range(W):
                if not removed[i][j]:
                    remaining_in_row.append(j)

            if len(remaining_in_row) >= 2:
                first_char = grid[i][remaining_in_row[0]]
                all_same = True
                for j in remaining_in_row:
                    if grid[i][j] != first_char:
                        all_same = False
                        break
                if all_same:
                    marked_this_round = True
                    for j in remaining_in_row:
                        to_remove.append((i, j))

        # 2. Check Columns
        cols_to_check = list(active_cols)
        for j in cols_to_check:
            remaining_in_col = []
            for i in range(H):
                if not removed[i][j]:
                    remaining_in_col.append(i)

            if len(remaining_in_col) >= 2:
                first_char = grid[remaining_in_col[0]][j]
                all_same = True
                for i in remaining_in_col:
                    if grid[i][j] != first_char:
                        all_same = False
                        break
                if all_same:
                    marked_this_round = True
                    for i in remaining_in_col:
                        to_remove.append((i, j))

        if not marked_this_round:
            break

        # 3. Remove marked cookies and update active sets
        for i, j in to_remove:
            if not removed[i][j]:
                removed[i][j] = True
                # We don't necessarily remove the row/col from active sets here,
                # but we could optimize by checking if a row/col is now empty.

        # Update active rows and columns: only keep those that have at least 2 cookies
        # Actually, just re-scanning is fine given the constraints if we are careful,
        # but the problem asks to return to step 1. 
        # To ensure efficiency, we only re-check rows/cols that were affected.
        # For simplicity in Python, since H, W <= 2000, the O(K * (H*W)) might be slow.
        # However, once a row/column is gone or has < 2 elements, it can never be cleared again.

        # Optimization: Row/Col can only be cleared if it contains >= 2 elements.
        # We check which rows/cols still have at least 2 elements.
        new_active_rows = set()
        for i in range(H):
            count = 0
            for j in range(W):
                if not removed[i][j]:
                    count += 1
                    if count >= 2:
                        new_active_rows.add(i)
                        break
        active_rows = new_active_rows

        new_active_cols = set()
        for j in range(W):
            count = 0
            for i in range(H):
                if not removed[i][j]:
                    count += 1
                    if count >= 2:
                        new_active_cols.add(j)
                        break
        active_cols = new_active_cols

    # Count remaining
    count = 0
    for i in range(H):
        for j in range(W):
            if not removed[i][j]:
                count += 1
    print(count)

if __name__ == "__main__":
    solve()
