def min_length(s: str) -> int:
    stack = []
    for char in s:
        if stack:
            # Check if the current character forms "AB" or "CD" with the top of the stack
            if (stack[-1] == 'A' and char == 'B') or (stack[-1] == 'C' and char == 'D'):
                stack.pop()
                continue
        stack.append(char)
    return len(stack)
