def longestSpecialSubstring(s: str) -> int:
    n = len(s)
    max_len = -1

    # Since the string length is small (up to 50), 
    # we can iterate through all possible substrings.
    # A special substring consists of only one unique character.
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            substring = s[i:i + length]

            # Check if the substring is "special"
            if len(set(substring)) == 1:
                # Count occurrences of this special substring in the whole string
                # We need to find all starting positions j such that s[j:j+length] == substring
                count = 0
                for j in range(n - length + 1):
                    if s[j:j + length] == substring:
                        count += 1

                if count >= 3:
                    max_len = max(max_len, length)

    return max_len
