def countBeautifulSubstrings(s: str, k: int) -> int:
    vowels_set = set('aeiou')
    n = len(s)
    count = 0

    # Iterate through all possible starting points of substrings
    for i in range(n):
        vowels = 0
        consonants = 0
        # Iterate through all possible ending points starting from i
        for j in range(i, n):
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # Check the conditions for a beautiful substring
            # 1. vowels == consonants
            # 2. (vowels * consonants) % k == 0
            if vowels == consonants:
                if (vowels * consonants) % k == 0:
                    count += 1

    return count
