def shortestUniqueSubstrings(arr):
    from collections import Counter

    n = len(arr)
    # Count occurrences of all possible substrings across all strings in the array
    substring_counts = Counter()
    for s in arr:
        unique_subs_in_s = set()
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                unique_subs_in_s.add(s[i:j])
        for sub in unique_subs_in_s:
            substring_counts[sub] += 1

    answer = []
    for s in arr:
        best_sub = ""
        # Iterate through possible lengths of substrings from 1 up to the length of s
        for length in range(1, len(s) + 1):
            candidates = []
            for i in range(len(s) - length + 1):
                sub = s[i:i + length]
                # A substring is unique to this string if it appears exactly once in the total set 
                # of unique-per-string counts (which corresponds to only appearing in this current arr[i])
                if substring_counts[sub] == 1:
                    candidates.append(sub)

            if candidates:
                # If we found any candidates of this length, take the lexicographically smallest
                best_sub = min(candidates)
                break # Since we want the shortest length, we stop at the first length that yields candidates

        answer.append(best_sub)

    return answer
