def longestCommonSufix(wordsContainer, wordsQuery):
    # We use a Trie to store the reversed words of wordsContainer.
    # This allows us to find the longest common suffix by traversing the Trie.
    trie = {}

    # To track the best index for each node in the Trie:
    # best_idx[node] = the index of the string that is the shortest and appears first.
    best_idx = {}

    for i, word in enumerate(wordsContainer):
        # Use reverse word to treat suffix as prefix
        rev_word = word[::-1]
        curr = trie

        # We need to determine the best index for the root and all nodes along the path.
        # A "better" index is one with a shorter word length, then a smaller index.
        # We update the root's best index first (case for no common suffix).

        # Custom logic for updating the best index:
        # We store (length, index) and compare.
        def update_best(node):
            if node not in best_idx:
                best_idx[node] = i
            else:
                prev_idx = best_idx[node]
                if len(wordsContainer[i]) < len(wordsContainer[prev_idx]):
                    best_idx[node] = i
                # If lengths are equal, the existing index is already smaller (occurred earlier)

        # The root is always part of every search
        update_best(id(trie)) # Using a proxy for root since dicts aren't hashable easily in this way, 
                               # but we can just use a special key or handle it separately.

        # Instead of id(trie), let's use a dedicated logic.

    # Let's redefine the Trie logic more cleanly.
    root = {}
    # root_best stores the index of the shortest word in wordsContainer.
    root_best = 0
    for i in range(1, len(wordsContainer)):
        if len(wordsContainer[i]) < len(wordsContainer[root_best]):
            root_best = i

    for i, word in enumerate(wordsContainer):
        curr = root
        rev_word = word[::-1]
        for char in rev_word:
            if char not in curr:
                curr[char] = {}
                # New node: current word is the first and thus the best so far.
                curr[char]['_best'] = i
            else:
                # Compare current word length with the current best index at this node.
                best_i = curr[char]['_best']
                if len(word) < len(wordsContainer[best_i]):
                    curr[char]['_best'] = i
            curr = curr[char]

    ans = []
    for query in wordsQuery:
        rev_query = query[::-1]
        curr = root
        best_found = root_best
        for char in rev_query:
            if char in curr:
                curr = curr[char]
                best_found = curr['_best']
            else:
                break
        ans.append(best_found)

    return ans
