def medianOfUniquenessArray(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    median_pos = (total_subarrays + 1) // 2

    def count_subarrays_with_at_most_k_distinct(k):
        count = 0
        left = 0
        freq = {}
        distinct_elements = 0
        for right in range(n):
            if nums[right] not in freq or freq[nums[right]] == 0:
                distinct_elements += 1
            freq[nums[right]] = freq.get(nums[right], 0) + 1

            while distinct_elements > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    distinct_elements -= 1
                left += 1

            count += (right - left + 1)
        return count

    low = 1
    high = len(set(nums))
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_subarrays_with_at_most_k_distinct(mid) >= median_pos:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
