import sys

def solve():
    # Read all input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])

    # Pre-calculate the distance matrix for easier access
    # dist[i][j] will store weight between vertex i and j (0-indexed)
    dist = [[0] * N for _ in range(N)]
    ptr = 1
    for i in range(N - 1):
        for j in range(i + 1, N):
            dist[i][j] = dist[j][i] = int(input_data[ptr])
            ptr += 1

    # DP with bitmask: dp[mask] is the max weight using vertices in mask
    # mask is a bitmask where the i-th bit is 1 if vertex i is used
    dp = [-1] * (1 << N)
    dp[0] = 0

    for mask in range(1 << N):
        if dp[mask] == -1:
            continue

        # Find the first vertex not in the mask to reduce redundant transitions
        first_free = -1
        for i in range(N):
            if not (mask & (1 << i)):
                first_free = i
                break

        if first_free == -1:
            continue

        # Option 1: Skip the first_free vertex (it remains unmatched)
        new_mask_skip = mask | (1 << first_free)
        if dp[new_mask_skip] < dp[mask]:
            dp[new_mask_skip] = dp[mask]

        # Option 2: Match first_free vertex with some other free vertex j
        for j in range(first_free + 1, N):
            if not (mask & (1 << j)):
                new_mask_match = mask | (1 << first_free) | (1 << j)
                weight = dp[mask] + dist[first_free][j]
                if dp[new_mask_match] < weight:
                    dp[new_mask_match] = weight

    print(dp[(1 << N) - 1])

if __name__ == "__main__":
    solve()

