import sys
from collections import deque

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_pos = (r, c)
            elif char == 'G':
                goal_pos = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # All points of interest: Start, Candies..., Goal
    nodes = [start_pos] + candies + [goal_pos]
    num_nodes = len(nodes)
    dist_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    # BFS from each point of interest to find shortest paths to all others
    for i in range(num_nodes):
        sr, sc = nodes[i]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for j in range(num_nodes):
            tr, tc = nodes[j]
            if dists[tr][tc] != -1:
                dist_matrix[i][j] = dists[tr][tc]

    # TSP-like DP
    # dp[mask][i] = minimum time to visit candies in mask, ending at candy i
    # mask is a bitmask of the 'candies' list (excluding start and goal)
    num_candies = len(candies)
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Base case: start to first candy
    for i in range(num_candies):
        # nodes[0] is start, nodes[1...num_candies] are candies
        dp[1 << i][i] = dist_matrix[0][i + 1]

    # Fill DP
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue
            # Try moving to next candy j
            for j in range(num_candies):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    # dist_matrix indices: start=0, candies=1..num_candies, goal=num_nodes-1
                    new_dist = dp[mask][i] + dist_matrix[i + 1][j + 1]
                    if new_dist < dp[new_mask][j]:
                        dp[new_mask][j] = new_dist

    # The goal node is at index num_nodes - 1
    goal_idx = num_nodes - 1
    max_candies = -1

    # Check if we can reach goal from start without any candies
    if dist_matrix[0][goal_idx] <= T:
        max_candies = 0

    # Check if we can reach goal after visiting a subset of candies
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue
            # Distance from last candy to goal
            total_dist = dp[mask][i] + dist_matrix[i + 1][goal_idx]
            if total_dist <= T:
                # Count set bits in mask
                visited_count = bin(mask).count('1')
                if visited_count > max_candies:
                    max_candies = visited_count

    print(max_candies)

if __name__ == "__main__":
    solve()

```

