def max_element_sum(nums):
    """
    Two numbers a and b satisfy the property that a * b is a perfect square 
    if and only if they have the same square-free part.
    The square-free part of a number is the product of all prime factors 
    that appear an odd number of times in its prime factorization.
    """
    def get_square_free_part(n):
        res = 1
        d = 2
        temp = n
        while d * d <= temp:
            if temp % d == 0:
                count = 0
                while temp % d == 0:
                    count += 1
                    temp //= d
                if count % 2 == 1:
                    res *= d
            d += 1
        if temp > 1:
            res *= temp
        return res

    sums = {}
    for num in nums:
        sf = get_square_free_part(num)
        sums[sf] = sums.get(sf, 0) + num

    return max(sums.values()) if sums else 0
