def isGoodArray(nums):
    # The length of the array must be n + 1
    # Therefore, n = len(nums) - 1
    n = len(nums) - 1
    if n < 1:
        return False

    # Find the maximum element in the array
    max_val = max(nums)

    # For the array to be a permutation of base[n], 
    # the maximum value must be exactly n.
    if max_val != n:
        return False

    # Count the occurrences of each number
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    # Check if all numbers from 1 to n-1 appear exactly once
    for i in range(1, n):
        if counts.get(i, 0) != 1:
            return False

    # Check if the number n appears exactly twice
    if counts.get(n, 0) != 2:
        return False

    return True
