import heapq

def minCostToConvert(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # We need to find the shortest path between all pairs of lowercase English letters.
    # Since there are only 26 characters, we can use the Floyd-Warshall algorithm.
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # Distance to self is 0
    for i in range(26):
        dist[i][i] = 0

    # Fill in initial costs from the provided arrays
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd-Warshall algorithm for all-pairs shortest path
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] != inf and dist[k][j] != inf:
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    # Iterate through the source and target strings to calculate the total cost
    for s, t in zip(source, target):
        if s == t:
            continue
        u = ord(s) - ord('a')
        v = ord(t) - ord('a')
        if dist[u][v] == inf:
            return -1
        total_cost += dist[u][v]

    return total_cost
