def shortestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    min_len = float('inf')
    best_substring = ""

    # Sliding window or double loop to find all substrings with exactly k 1s
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            if ones_count == k:
                current_len = j - i + 1
                current_substring = s[i:j+1]

                if current_len < min_len:
                    min_len = current_len
                    best_substring = current_substring
                elif current_len == min_len:
                    if current_substring < best_substring:
                        best_substring = current_substring

                # Since we are looking for the shortest, once we reach k ones, 
                # any further expansion of j will only increase the length.
                break
            elif ones_count > k:
                break

    return best_substring
