import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    H = int(input_data[1])
    W = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # grid to keep track of filled cells
    grid = [[False for _ in range(W)] for _ in range(H)]
    used = [False] * N

    def find_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack():
        empty = find_empty()
        if empty is None:
            return True

        r, c = empty

        # Try every available tile
        for i in range(N):
            if not used[i]:
                used[i] = True
                # Try both orientations (A x B and B x A)
                # We use a set to avoid duplicate checks if A == B
                orientations = set([(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])])
                for h, w in orientations:
                    if can_place(r, c, h, w):
                        place(r, c, h, w, True)
                        if backtrack():
                            return True
                        place(r, c, h, w, False)
                used[i] = False

        return False

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

