import sys

def solve():
    # Read H, W, K from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    K = int(input_data[2])
    S = input_data[3:]

    min_ops = float('inf')

    # Check horizontal sequences
    if W >= K:
        for i in range(H):
            row = S[i]
            # We use a sliding window to count '.' and check for 'x'
            current_dots = 0
            current_x = 0

            # Initialize first window of size K
            for j in range(K):
                if row[j] == '.':
                    current_dots += 1
                elif row[j] == 'x':
                    current_x += 1

            if current_x == 0:
                min_ops = min(min_ops, current_dots)

            # Slide the window across the row
            for j in range(K, W):
                # Remove leftmost element
                if row[j - K] == '.':
                    current_dots -= 1
                elif row[j - K] == 'x':
                    current_x -= 1
                # Add rightmost element
                if row[j] == '.':
                    current_dots += 1
                elif row[j] == 'x':
                    current_x += 1

                if current_x == 0:
                    min_ops = min(min_ops, current_dots)

    # Check vertical sequences
    if H >= K:
        for j in range(W):
            # Extract column as a string/list for easier processing
            col = [S[i][j] for i in range(H)]
            current_dots = 0
            current_x = 0

            # Initialize first window of size K
            for i in range(K):
                if col[i] == '.':
                    current_dots += 1
                elif col[i] == 'x':
                    current_x += 1

