def count_matching_subarrays(nums, pattern):
    n = len(nums)
    m = len(pattern)
    count = 0

    # A subarray of size m + 1 starts at index i
    # The range of i is from 0 to n - (m + 1) inclusive
    for i in range(n - m):
        match = True
        for k in range(m):
            # Compare nums[i + k] and nums[i + k + 1] based on pattern[k]
            diff = 0
            if nums[i + k + 1] > nums[i + k]:
                diff = 1
            elif nums[i + k + 1] < nums[i + k]:
                diff = -1
            else:
                diff = 0

            if diff != pattern[k]:
                match = False
                break

        if match:
            count += 1

    return count
