import math

def canConnectAll(nums):
    if len(nums) == 1:
        return True

    # Disjoint Set Union (DSU) to manage components
    parent = list(range(len(nums)))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the first index encountered that has this factor
    # This avoids O(N^2) GCD checks
    prime_to_index = {}

    for i, val in enumerate(nums):
        # Basic prime factorization
        d = 2
        temp = val
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all elements belong to the same component
    root = find(0)
    for i in range(1, len(nums)):
        if find(i) != root:
            return False

    return True
