def specialPermutations(nums):
    import functools

    n = len(nums)
    MOD = 10**9 + 7

    # Precompute divisibility matrix to speed up transitions
    # adj[i][j] is True if nums[i] and nums[j] can be adjacent
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    adj[i][j] = True

    @functools.lru_cache(None)
    def solve(mask, last_idx):
        # mask: bitmask representing the set of visited elements
        # last_idx: the index of the last element added to the permutation

        # If all elements are visited, we found one valid permutation
        if mask == (1 << n) - 1:
            return 1

        count = 0
        # Try adding every element that hasn't been visited yet
        for next_idx in range(n):
            if not (mask & (1 << next_idx)):
                # Check if the next element can follow the last element
                if adj[last_idx][next_idx]:
                    count += solve(mask | (1 << next_idx), next_idx)

        return count % MOD

    total_special_permutations = 0
    # Start the permutation with each possible element in the array
    for i in range(n):
        total_special_permutations += solve(1 << i, i)

    return total_special_permutations % MOD
